"""Render the saved metrics into a local, inspectable diagnostics page."""
import html
import json
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo
ROOT=Path(__file__).resolve().parents[1]
def main():
    r=json.loads((ROOT/'artifacts/realism/generator-comparison.json').read_text())
    v=json.loads((ROOT/'artifacts/realism/real-data-validation.json').read_text())
    labels={'pass_distance_m':('Average ground pass distance',' m',1),'pass_completion':('Ground pass completion','%',100),
            'backward_pass_share':('Backward pass share','%',100),'shot_distance_m':('Average shot distance',' m',1),
            'shot_conversion':('Shot conversion','%',100)}
    rows=[]
    for key,(label,unit,factor) in labels.items():
        values=[r[group][key]*factor for group in ('real_held_out','baseline','modified')]
        improved=r['absolute_gaps'][key]['after']<r['absolute_gaps'][key]['before']
        rows.append('<tr><th>'+label+'</th>'+''.join(f'<td>{value:.2f}{unit}</td>' for value in values)+f'<td>{"Gap narrowed" if improved else "Gap widened, to be corrected"}</td></tr>')
    before=sum(g['unpressured_large_backpasses_near_goal'] for g in r['baseline_matches'])
    after=sum(g['unpressured_large_backpasses_near_goal'] for g in r['modified_matches'])
    models=''.join(f'<tr><th>{kind}</th><td>{m["n"]}</td><td>{m["constant_train_prior_brier"]:.5f}</td><td>{m["brier"]:.5f}</td></tr>' for kind,m in v['predictive_metrics'].items())
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NextPlay · Real-data calibration validation</title><style>body{font:17px/1.7 system-ui;background:#101e25;color:#e1ece6;max-width:1050px;margin:40px auto;padding:0 24px}a{color:#9edbbb}table{border-collapse:collapse;width:100%;margin:24px 0}th,td{padding:12px;border-bottom:1px solid #416056;text-align:left}section{background:#1c3037;padding:24px;margin:24px 0;border-radius:12px}.note{color:#ffd78c}code{overflow-wrap:anywhere}</style><a href="coach.html?realism=1">← View the new simulation sample</a><h1>Real-data calibration and simulation validation</h1><p>Generator v2.2.0 · synthetic matches; real events provide the statistical reference. No best-decision score or professional-grade football engine is claimed.</p><section><h2>Three same-seed matches: before and after the change</h2><p>Seeds: 20261019, 12345, 712. The real reference in the table below comes from the final independent 8 matches; distances are rescaled to a 105 × 68 m pitch. The new policy generates ground passes only, so the ground-pass calibration is not carried over to lofted balls. Only footed ground passes and footed shots are compared. The original simulation moved some unsuccessful passes towards a defender, so the endpoint definition still differs.</p><table><thead><tr><th>Metric</th><th>Real reference</th><th>Old generator</th><th>New generator</th><th>Gap vs. real reference</th></tr></thead><tbody>'''+''.join(rows)+f'''</tbody></table><p>Large back passes with no obvious pressure in front of goal: {before} → {after} (3 matches in total). Diagnostic definition: an attacking coordinate beyond 88 m, more than 30 m backwards, and an event not marked as under pressure; the policy's down-weighting condition is stricter and requires the nearest defender to be more than 4 m away. It is not a manual "wrong decision" label.</p><p class="note">The overall backward pass share is still too high, and it is further from the real reference than in the old version. This may be linked to the fixed formation and to the forced carry that advances the ball in front of a teammate; the next step is to validate off-ball support and the distribution of possession zones. An improvement in a local metric must not be presented as the whole-match tactics already being realistic.</p></section><section><h2>Scoring model: test on independent real matches</h2><table><thead><tr><th>Model</th><th>Events</th><th>Constant baseline Brier</th><th>Calibrated model Brier</th></tr></thead><tbody>'''+models+'''</tbody></table><p>Brier is the mean squared error between the predicted probability and the actual outcome; lower is better. The baseline uses only the overall completion rate / goal rate of the training set. Passes are grouped by distance and pressure, shots by distance, with smoothing applied. The test results were not used for training.</p><p class="note">The final test has only 50 footed shots, so the goal-rate estimate is unstable. An improvement in scoring does not prove that counterfactual actions or player positioning are correct.</p></section><section><h2>Data source, splits and limits</h2><p>Source: <a href="https://github.com/statsbomb/open-data">StatsBomb Open Data / Hudl</a>, 2022 World Cup. The first 32 matches are taken in match_id order: 16 calibration matches, 8 development check matches and another 8 as the final test. The first-round development results are kept, and the final test was not used to modify the policy.</p><p>Filter: both halves, Regular Play, footed ground passes / footed shots, with Carry included. Event counts are not equivalent decision opportunities, so regional action frequencies are only a reference for generation weights. The sample is not representative of the Premier League.</p><p>The data has no continuous tracking, so defensive positioning, body orientation, preferred foot, full collision physics and actions that did not occur cannot be validated. The original simplified shot save ratio, the handling of unsuccessful passes and the carry after a restart are still kept. The route feasibility index on the new analysis page is still an independent heuristic model, not a success probability produced by this calibration.</p><p>The raw data files are kept locally under .local/statsbomb and are not distributed publicly with the project; the profile and the validation JSON record the source URL, the version, the checksum and the training / test match IDs. When publishing results derived from the data, please follow the terms of the source repository and add the required StatsBomb attribution.</p><p>Data version: <code>'''+html.escape(v['source']['commit'])+'''</code></p><p><a href="artifacts/realism/real-data-validation.json">Scoring and source JSON</a> · <a href="artifacts/realism/generator-comparison.json">Simulation comparison JSON</a> · <a href="artifacts/realism/initial-development-comparison.json">First development round comparison</a></p></section></html>'''
    upgrade_path=ROOT/'decision/value-model.json'
    if upgrade_path.exists():
        upgrade=json.loads(upgrade_path.read_text());check=upgrade['validation']
        notice=f"<section><h2>New: actions and decisions are evaluated separately</h2><p><a href='action-review.html'>Open the upgraded action analysis page</a> · <a href='artifacts/realism/action-upgrade-validation.json'>Upgrade check record</a></p><p>A location-value model trained on real events: the target is a goal within at most 10 eligible on-ball actions of the same simplified possession. Tested on {check['test_actions']} actions, with {check['positive_goal_windows']} overlapping goal windows (not a count of independent goals); Brier {check['brier']:.6f}, constant training baseline {check['constant_train_baseline_brier']:.6f}. This only shows that location value has preliminary support; it does not mean the ranking of alternative options has been validated.</p><p>Passing, carrying, shooting and waiting all use the same value unit. The lane defensive adjustment and the possession retention weights for carry / wait remain rule assumptions. The sensitivity range is not a confidence interval. The actual execution outcome is revealed separately at the replay time and never feeds back into the pre-action score; without body orientation and touch information, no technical quality score is given.</p></section>"
        page=page.replace('<section>',notice+'<section>',1)
    from .render_system import section
    system=section(ROOT)
    page=page.replace('<section>',system+'<section>',1)
    refresh_path=ROOT/'artifacts/realism/data-refresh.json'
    if refresh_path.exists():
        refresh=json.loads(refresh_path.read_text())
        rows=''.join(f'<tr><th>{label}</th><td>{refresh["action_mix"]["shares"][kind]*100:.2f}%</td><td>{refresh["real_test_shares"][kind]*100:.2f}%</td></tr>'
                     for kind,label in (('pass','Pass'),('carry','Carry'),('shot','Shot')))
        notice=f'''<section><h2>Current data: the player attribute policy is applied</h2><p>{html.escape(refresh['generator'])} · {refresh['matches']} matches · {refresh['players']} players. The schedule and the random seeds are kept, and the results, the standings, the heatmaps, the decisions and the post-match analyses are recomputed. Below is the action mix of the current full league, excluding the forced carry after a restart.</p><table><thead><tr><th>Action</th><th>Current league</th><th>Real test reference</th></tr></thead><tbody>{rows}</tbody></table><p>The reference is ground passes, carries and footed shots from the World Cup data, and the denominator contains only these three action types. A matching share does not mean that all actions, the volume per minute or the individual style have been validated.</p><p><a href="artifacts/realism/data-refresh.json">This data refresh record</a> · <a href="artifacts/realism/player-action-validation.json">Independent seed calibration validation</a></p></section>'''
        page=page.replace('<section>',notice+'<section>',1)
        page=page.replace('Generator v2.2.0 · synthetic matches','Generator v2.3.0 · synthetic matches')
        page=page.replace('Three same-seed matches: before and after the change','Historical v2.2 calibration record: three same-seed matches compared')
    (ROOT/'realism-validation.html').write_text(page)

if __name__=='__main__': main()
